static void lesson_check(bool condition, const char *file, int line) {
  if (!condition) {
    fprintf(stderr, "Check failed at %s:%d\n", file, line);
    abort();
  }
}
#define CHECK(condition) lesson_check((condition), __FILE__, __LINE__)

/* Trace a prefix sum */
{
  int values[] = {2, 4, 6};
  int sum = 0;
  for (size_t i = 0; i < 3; i++) {
    sum += values[i];
  }
  CHECK(sum == 12);
}

/* Handle zero iterations */
{
  int values[1] = {9};
  size_t length = 0;
  int sum = 0;
  for (size_t i = 0; i < length; i++) {
    sum += values[i];
  }
  CHECK(sum == 0);
}

/* Find the first match */
{
  int values[] = {3, 8, 8};
  size_t found = 3;
  for (size_t i = 0; i < 3; i++) {
    if (values[i] == 8) {
      found = i;
      break;
    }
  }
  CHECK(found == 1);
}

/* Include an exact threshold */
{
  int score = 60;
  bool passed = score >= 60;
  CHECK(passed);
}

/* Terminate a switch case */
{
  int code = 2, result = 0;
  switch (code) {
  case 1:
    result = 10;
    break;
  case 2:
    result = 20;
    break;
  default:
    result = -1;
    break;
  }
  CHECK(result == 20);
}

  /* Transfer reverse traversal safely */
  {
    int values[] = {1, 2, 3};
    int out = 0;
    for (size_t remaining = 3; remaining > 0; remaining--) {
      size_t i = remaining - 1;
      out = out * 10 + values[i];
    }
    CHECK(out == 321);
  }
  puts("All lesson checks passed.");
  return 0;
}

struct Vector {
  int *data;
  size_t len, cap;
};

static bool vector_reserve(struct Vector *v, size_t cap) {
  if (cap <= v->cap)
    return true;
  if (cap > SIZE_MAX / sizeof *v->data)
    return false;
  int *next = realloc(v->data, cap * sizeof *v->data);
  if (next == NULL)
    return false;
  v->data = next;
  v->cap = cap;
  return true;
}

static bool vector_push(struct Vector *v, int value) {
  if (v->len == v->cap) {
    size_t next = v->cap ? v->cap * 2 : 4;
    if (next < v->cap || !vector_reserve(v, next))
      return false;
  }
  v->data[v->len++] = value;
  return true;
}

static bool vector_pop(struct Vector *v, int *out) {
  if (v->len == 0 || out == NULL)
    return false;
  *out = v->data[--v->len];
  return true;
}
static void vector_destroy(struct Vector *v) {
  free(v->data);
  v->data = NULL;
  v->len = 0;
  v->cap = 0;
}

int main(void) {
  /* Push into an empty vector */
  {
    struct Vector v = {0};
    CHECK(vector_push(&v, 3) && vector_push(&v, 5));
    CHECK(v.len == 2 && v.data[0] == 3 && v.data[1] == 5);
    vector_destroy(&v);
  }

  /* Reserve without adding elements */
  {
    struct Vector v = {0};
    CHECK(vector_reserve(&v, 8));
    CHECK(v.cap >= 8 && v.len == 0);
    vector_destroy(&v);
  }

  /* Grow while preserving contents */
  {
    struct Vector v = {0};
    for (int i = 0; i < 20; i++)
      CHECK(vector_push(&v, i));
    for (size_t i = 0; i < v.len; i++)
      CHECK(v.data[i] == (int)i);
    vector_destroy(&v);
  }

  /* Pop from a nonempty vector */
  {
    struct Vector v = {0};
    int out = 0;
    CHECK(vector_push(&v, 7));
    CHECK(vector_pop(&v, &out) && out == 7 && v.len == 0);
    vector_destroy(&v);
  }

  /* Reject an empty pop */
  {
    struct Vector v = {0};
    int out = 9;
    CHECK(!vector_pop(&v, &out) && out == 9);
    vector_destroy(&v);
  }

  /* Transfer reserve failure atomicity */
  {
    struct Vector v = {0};
    CHECK(vector_push(&v, 4));
    CHECK(!vector_reserve(&v, SIZE_MAX));
    CHECK(v.len == 1 && v.data[0] == 4);
    vector_destroy(&v);
  }
  puts("All lesson checks passed.");
  return 0;
}

static bool add_checked(int a, int b, int *out) {
  if (out == NULL || (b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b))
    return false;
  *out = a + b;
  return true;
}

static bool size_product(size_t a, size_t b, size_t *out) {
  if (out == NULL || (b != 0 && a > SIZE_MAX / b))
    return false;
  *out = a * b;
  return true;
}

int main(void) {
  /* Add ordinary values */
  {
    int out = 0;
    CHECK(add_checked(7, 5, &out) && out == 12);
  }

  /* Reject positive overflow */
  {
    int out = 9;
    CHECK(!add_checked(INT_MAX, 1, &out) && out == 9);
  }

  /* Reject negative overflow */
  {
    int out = 9;
    CHECK(!add_checked(INT_MIN, -1, &out) && out == 9);
  }

  /* Accept exact boundaries */
  {
    int out = 0;
    CHECK(add_checked(INT_MAX, 0, &out) && out == INT_MAX);
    CHECK(add_checked(INT_MIN, 0, &out) && out == INT_MIN);
  }

  /* Reject a size product */
  {
    size_t out = 7;
    CHECK(!size_product(SIZE_MAX, 2, &out) && out == 7);
  }

  /* Transfer the zero product */
  {
    size_t out = 7;
    CHECK(size_product(SIZE_MAX, 0, &out) && out == 0);
  }
  puts("All lesson checks passed.");
  return 0;
}
